with prev_events as (select *, lag(started_at) over (partition by browser order by started_at asc, id asc) as prev_started_at from sessions), gaps as (select *, case when prev_started_at is null or started_at > prev_started_at + interval '90' day then 1 else 0 end as new_group_flag from prev_events) select *, sum(new_group_flag) over (partition by browser order by started_at asc, id asc rows between unbounded preceding and current row) as session_id from gaps
